import{_ as t,l as s,o as e,c as l,v as o,p as n,x as r,d,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"同源与 CSRF","description":"","frontmatter":{"title":"同源与 CSRF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/same-origin-csrf.md","filePath":"cs/same-origin-csrf.md","lastUpdated":1789023840000}'),S={name:"cs/same-origin-csrf.md"};function p(h,a,B,C,m,_){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="同源与-csrf" tabindex="-1">同源与 CSRF <a class="header-anchor" href="#同源与-csrf" aria-label="Permalink to &quot;同源与 CSRF&quot;">​</a></h1><div class="epigraph"><p>浏览器按源隔离脚本能读的数据；跨站请求仍会自动带上用户的 Cookie，于是「谁在发」与「谁想发」可以分开。</p><footer>—— 据浏览器同源政策；Anderson 对混淆代理人；RFC 9110 的 Cookie 对照</footer></div><p><a href="/cs/dos-amplify">上一课</a>处理可用性上的洪水与放大。本课不重做放大因子。缺口是 Web 客户端：同源政策（SOP）挡住读，挡不住浏览器对另一站自动出示凭证。CSRF：外站诱导浏览器对目标站发带身份的请求。防御是分离「浏览器已登录」与「用户意图」。注入下一课是解释器边界。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DoS 课打 A。Web 应用还把会话放在 Cookie。SOP：不同源的脚本不能读对方 DOM 与多数响应。表单与部分请求仍可跨源发出，Cookie 默认随行——这是混淆代理人：浏览器是用户的代理人，却被另一源驱使。缺口是<strong>同源只管机密性读取，不管跨站写请求</strong>。本课不给诱骗页面配方。</p><p><span class="marginnote">SameSite Cookie、反 CSRF 令牌、要求自定义头，都是把「有意图」绑进请求。CORS 是读响应的放行名单，不是 CSRF 的完整解。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>防御合同：状态改变用非简单请求或带不可预测令牌；Cookie 设 SameSite；关键操作再认证。SOP 仍是读隔离的基石。本课只讲机制：自动凭证 + 跨站发出 = 意图缺失。</p>',8)),(e(),n(E,null,{default:r(()=>[c(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SOP%5B%22%E5%90%8C%E6%BA%90%3A%20%E9%99%90%E5%88%B6%E8%AF%BB%22%5D%20--%3E%20COOKIE%5B%22%E8%B7%A8%E7%AB%99%E8%AF%B7%E6%B1%82%E4%BB%8D%E5%8F%AF%E5%B8%A6%20Cookie%22%5D%0A%20%20COOKIE%20--%3E%20CSRF%5B%22%E7%9B%AE%E6%A0%87%E7%AB%99%E5%BD%93%E6%88%90%E7%94%A8%E6%88%B7%E6%84%8F%E5%9B%BE%22%5D%0A%20%20TOK%5B%22%E4%BB%A4%E7%89%8C%20%2F%20SameSite%22%5D%20--%3E%20BIND%5B%22%E6%8A%8A%E6%84%8F%E5%9B%BE%E7%BB%91%E8%BF%9B%E8%AF%B7%E6%B1%82%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>CSRF 不需要读出 Cookie 值，只要让浏览器发出去——因此只加密（TLS）不够，中间人课的认证也不自动修。它与<a href="/cs/oauth-oidc">OAuth</a> 的 redirect 风险同构：代理人被第三方利用。最小特权：会话 Cookie 不要过宽路径。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 XSS 与 CSRF 混成一课；脚本注入是下一课解释器边界。也不把全部 CORS 头当百科。</p><p>后课默认：跨站请求不等于用户意图。不可信字符串进入解释器是另一边界。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>SOP 隔离读；CSRF 利用自动凭证发写请求。</li><li>防御是意图绑定，不是再加一层 TLS。</li><li>注入作为输入边界下一课。</li><li>出处：同源政策；Anderson；对照 RFC 9110。</li></ul>',7))])}const u=t(S,[["render",p]]);export{f as __pageData,u as default};
